package com.aidevos.orchestrator.qualitygate;
import java.util.List; import java.util.Map; import java.util.concurrent.ConcurrentHashMap; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="aidevos.persistence",name="type",havingValue="in-memory",matchIfMissing=true)
public class InMemoryQualityGateRepository implements QualityGateRepository { private final Map<String,QualityGateResult> values=new ConcurrentHashMap<>(); public void save(QualityGateResult r){values.put(r.getGateResultId(),r);} public QualityGateResult get(String id){return values.get(id);} public List<QualityGateResult> findByValidationRunId(String id){return values.values().stream().filter(r->id.equals(r.getValidationRunId())).toList();} }
